window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-96576f8743b2bfc0"]={"versions": [{"id": "FIG-96576f8743b2bfc0", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene) aus der AUTOSAR Classic RTE-Spezifikation zur Veranschaulichung der Modellierung einer Typ-Neudefinition (<code>TYPE_REFERENCE</code>) auf M1-Modellebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Instanz <code>EngSpd :ImplementationDataType</code>: Linkes Datenobjekt mit Attributwert <code>category = TYPE_REFERENCE</code>.</li>\n<li>Instanz <code>:SwDataDefProps</code>: Zentrales Eigenschaftsobjekt, aggregiert über Kompositionsbeziehung mit Rollenbezeichnung <code>+swDataDefProps</code> von <code>EngSpd</code>.</li>\n<li>Instanz <code>uint16 :ImplementationDataType</code>: Rechtes Ziel-Datenobjekt, referenziert über gerichtete Assoziation mit Rollenbezeichnung <code>+implementationDataType</code> von <code>:SwDataDefProps</code>.</li>\n<li>UML-Notizsymbol: Zugeordneter C-Code <code>typedef uint16 EngSpd;</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm ohne Verhaltens- oder Sequenzabläufe. Die Instanzbeziehungen bilden die statische Deklaration einer Typ-Neudefinition in der AUTOSAR-Entwurfszeit ab.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert das metamodellkonforme Mapping für die Generierung von Typ-Aliassen (<code>typedef</code>) im RTE-Header: Ein <code>ImplementationDataType</code> der Kategorie <code>TYPE_REFERENCE</code> verweist über seine eingebetteten <code>swDataDefProps</code> mittels <code>implementationDataType</code> auf den zugrundeliegenden Basistyp (<code>uint16</code>), woraus der C-Code <code>typedef uint16 EngSpd;</code> resultiert.</p>"}, {"id": "FIG-4f19b94ef5a38aa7", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene) aus der AUTOSAR Classic RTE-Spezifikation zur Veranschaulichung der Modellierung einer Typ-Neudefinition (<code>TYPE_REFERENCE</code>) auf M1-Modellebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Instanz <code>EngSpd :ImplementationDataType</code>: Linkes Datenobjekt mit Attributwert <code>category = TYPE_REFERENCE</code>.</li>\n<li>Instanz <code>:SwDataDefProps</code>: Zentrales Eigenschaftsobjekt, aggregiert über Kompositionsbeziehung mit Rollenbezeichnung <code>+swDataDefProps</code> von <code>EngSpd</code>.</li>\n<li>Instanz <code>uint16 :ImplementationDataType</code>: Rechtes Ziel-Datenobjekt, referenziert über gerichtete Assoziation mit Rollenbezeichnung <code>+implementationDataType</code> von <code>:SwDataDefProps</code>.</li>\n<li>UML-Notizsymbol: Zugeordneter C-Code <code>typedef uint16 EngSpd;</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm ohne Verhaltens- oder Sequenzabläufe. Die Instanzbeziehungen bilden die statische Deklaration einer Typ-Neudefinition in der AUTOSAR-Entwurfszeit ab.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert das metamodellkonforme Mapping für die Generierung von Typ-Aliassen (<code>typedef</code>) im RTE-Header: Ein <code>ImplementationDataType</code> der Kategorie <code>TYPE_REFERENCE</code> verweist über seine eingebetteten <code>swDataDefProps</code> mittels <code>implementationDataType</code> auf den zugrundeliegenden Basistyp (<code>uint16</code>), woraus der C-Code <code>typedef uint16 EngSpd;</code> resultiert.</p>"}], "trans": [{"from": "FIG-96576f8743b2bfc0", "to": "FIG-4f19b94ef5a38aa7", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
